<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use App\Models\Employee;
use App\Models\Paklaring;
use Carbon\Carbon;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Schema;

class PaklaringController extends Controller
{
    /**
     * Data base64 blangko sertifikat paklaring asli (resolusi tinggi 2480x1754 px)
     * Lengkap dengan logo, watermark G, stempel dan tanda tangan resmi.
     */
    public const BASE64_TEMPLATE = '';

    /**
     * Mendapatkan URL gambar template paklaring secara cerdas.
     * Jika file fisik belum ada di hosting cPanel, method ini otomatis membuatkan
     * file fisik exact_base_template.png di public/images/paklaring/, atau fallback ke Data URI.
     */
    public static function getTemplateUrl(): string
    {
        $path = public_path('images/paklaring/exact_base_template.png');

        if (!file_exists($path)) {
            try {
                $dir = dirname($path);
                if (!is_dir($dir)) {
                    @mkdir($dir, 0755, true);
                }
                @file_put_contents($path, base64_decode(self::BASE64_TEMPLATE));
            } catch (\Throwable $e) {}
        }

        if (file_exists($path)) {
            return asset('images/paklaring/exact_base_template.png') . '?v=' . filemtime($path);
        }

        return 'data:image/png;base64,' . self::BASE64_TEMPLATE;
    }

    public function index(Request $request)
    {
        $user = Auth::user();
        if (!$user || !$user->canManagePaklaring()) {
            abort(403, 'Akses terbatas untuk Departemen HR dan Direktur.');
        }

        $employees = Employee::orderBy('name')->get();

        $paklarings = collect();
        if (Schema::hasTable('paklarings')) {
            try {
                $paklarings = Paklaring::with(['employee', 'creator'])->latest()->paginate(10);
            } catch (\Exception $e) {
                // Table might not be migrated yet
            }
        }

        // Default initial values matching user template
        $defaults = [
            'recipient_name' => 'Rida Rapika Saragi',
            'program_or_position' => 'Program Pemagangan Kejuruan QC',
            'period_text' => 'Periode Tanggal 20 Juni 2021 s/d 31 Desember 2025',
            'company_unit' => 'PT. Sungshin Best Indonesia',
            'city' => 'Tangerang',
            'issue_date' => Carbon::now()->format('Y-m-d'),
            'formatted_issue_date' => Carbon::now()->locale('id')->translatedFormat('d F Y'),
            'signatory_name' => 'ANITA SANDRA DEWI',
            'signatory_title' => 'Direktur',
        ];

        $templateUrl = self::getTemplateUrl();

        return view('paklaring.index', compact('employees', 'paklarings', 'defaults', 'templateUrl'));
    }

    public function store(Request $request)
    {
        $user = Auth::user();
        if (!$user || !$user->canManagePaklaring()) {
            abort(403, 'Akses terbatas untuk Departemen HR dan Direktur.');
        }

        $validated = $request->validate([
            'recipient_name' => 'required|string|max:255',
            'program_or_position' => 'required|string|max:255',
            'period_text' => 'required|string|max:255',
            'company_unit' => 'required|string|max:255',
            'city' => 'required|string|max:100',
            'issue_date' => 'required|date',
            'employee_id' => 'nullable',
            'signatory_name' => 'nullable|string|max:255',
            'signatory_title' => 'nullable|string|max:255',
        ]);

        $year = Carbon::parse($validated['issue_date'])->format('Y');
        $certNumber = 'PKL/GYK/' . $year . '/' . strtoupper(substr(uniqid(), -5));

        $paklaring = Paklaring::create([
            'certificate_number' => $certNumber,
            'recipient_name' => $validated['recipient_name'],
            'employee_id' => !empty($request->input('employee_id')) ? $request->input('employee_id') : null,
            'program_or_position' => $validated['program_or_position'],
            'period_text' => $validated['period_text'],
            'company_unit' => $validated['company_unit'],
            'city' => !empty($validated['city']) ? $validated['city'] : 'Tangerang',
            'issue_date' => $validated['issue_date'],
            'signatory_name' => $request->input('signatory_name') ?: 'ANITA SANDRA DEWI',
            'signatory_title' => $request->input('signatory_title') ?: 'Direktur',
            'created_by' => $user->id,
        ]);

        if ($request->has('action_print')) {
            return redirect()->route('hr.paklaring.print', $paklaring->id);
        }

        return redirect()->route('hr.paklaring.index')->with('success', 'Surat Keterangan / Paklaring berhasil diterbitkan untuk ' . $validated['recipient_name']);
    }

    public function print($id)
    {
        $user = Auth::user();
        if (!$user || !$user->canManagePaklaring()) {
            abort(403, 'Akses terbatas untuk Departemen HR dan Direktur.');
        }

        $paklaring = Paklaring::findOrFail($id);

        $issueDateFormatted = Carbon::parse($paklaring->issue_date)->locale('id')->translatedFormat('d F Y');
        $templateUrl = self::getTemplateUrl();

        return view('paklaring.print', compact('paklaring', 'issueDateFormatted', 'templateUrl'));
    }

    public function directPrint(Request $request)
    {
        $user = Auth::user();
        if (!$user || !$user->canManagePaklaring()) {
            abort(403, 'Akses terbatas untuk Departemen HR dan Direktur.');
        }

        $recipient_name = $request->query('recipient_name', 'Rida Rapika Saragi');
        $program_or_position = $request->query('program_or_position', 'Program Pemagangan Kejuruan QC');
        $period_text = $request->query('period_text', 'Periode Tanggal 20 Juni 2021 s/d 31 Desember 2025');
        $company_unit = $request->query('company_unit', 'PT. Sungshin Best Indonesia');
        $city = $request->query('city', 'Tangerang');
        $issue_date = $request->query('issue_date', Carbon::now()->toDateString());
        $issueDateFormatted = Carbon::parse($issue_date)->locale('id')->translatedFormat('d F Y');
        $signatory_name = $request->query('signatory_name', 'ANITA SANDRA DEWI');
        $signatory_title = $request->query('signatory_title', 'Direktur');

        $paklaring = (object)[
            'recipient_name' => $recipient_name,
            'program_or_position' => $program_or_position,
            'period_text' => $period_text,
            'company_unit' => $company_unit,
            'city' => $city,
            'issue_date' => $issue_date,
            'signatory_name' => $signatory_name,
            'signatory_title' => $signatory_title,
        ];

        $templateUrl = self::getTemplateUrl();

        return view('paklaring.print', compact('paklaring', 'issueDateFormatted', 'templateUrl'));
    }

    /**
     * Endpoint untuk menyajikan gambar template background secara langsung.
     * Jika file fisik belum ada di hosting cPanel, method ini otomatis memulihkannya.
     */
    public function templateImage()
    {
        $path = public_path('images/paklaring/exact_base_template.png');

        if (!file_exists($path)) {
            try {
                $dir = dirname($path);
                if (!is_dir($dir)) {
                    @mkdir($dir, 0755, true);
                }
                @file_put_contents($path, base64_decode(self::BASE64_TEMPLATE));
            } catch (\Throwable $e) {}
        }

        if (file_exists($path)) {
            return response()->file($path, [
                'Content-Type' => 'image/png',
                'Cache-Control' => 'public, max-age=31536000',
            ]);
        }

        return response(base64_decode(self::BASE64_TEMPLATE), 200, [
            'Content-Type' => 'image/png',
            'Cache-Control' => 'public, max-age=31536000',
        ]);
    }

    public function destroy($id)
    {
        $user = Auth::user();
        if (!$user || !$user->canManagePaklaring()) {
            abort(403, 'Akses terbatas untuk Departemen HR dan Direktur.');
        }

        $paklaring = Paklaring::findOrFail($id);
        $paklaring->delete();

        return redirect()->route('hr.paklaring.index')->with('success', 'Data paklaring berhasil dihapus.');
    }
}